from taf.internal.managedobject import ManagedObject
from taf.internal.ue.pioneer.api.executor import TCPExecutor
from taf.internal.ue.pioneer.api.command import (
    AutoCheck, ConnectEQ, DisConnectEQ, StartLog, StopLog, StartULtraffic, StopULtraffic,
    Attach, Detach, PowerOn, PowerOff, LockBand, UnlockBand,
    Config5GDeployment, GetParamMAC, GetParamIMSI, GetPDUInfo, ExportMessageDetail,
    ExportLogfile, ConfigureAPN, SetupPDU, ReleasePDU, Config5GNRmeasurementAndEvent, SendAT, SetupS_NSSAI,
    GetAttachStatus, StartStatistics, StopStatistics, GetStatisticsResult, GetParamStatisticsResult,
    StartMOS, StopMOS, StartFTPDL, StartFTPUL, StartPing, StartHTTPPage, StopTest, StartCall, StartTraffic,
    StartCompositeTestPlan, GetParamSummaryStatisticsResult, Startup, Shutdown,
    PhysicalPowerOn, PhysicalPowerOff, GetParamIMEI, GetCAParamMAC, GetParamValue, GetModuleStatus,
    GetPortStatus, ExportLogfileData, GetParamIP, Query5GNRmeasurementAndEvent, ExportLayer2Msg,  ExportLayer1Msg,
    Reboot, GetAutoConnectInfo, GetDeviceInfo, StartPDUConn, SetAutoConnect, GetModuleSlotInfo)


class Pioneer(ManagedObject):
    def __init__(self, host, port=None, timeout=None):
        super(Pioneer, self).__init__()
        self._supported_commands = [
            AutoCheck, ConnectEQ, DisConnectEQ, StartLog, StopLog, StartULtraffic, StopULtraffic,
            Attach, Detach, PowerOn, PowerOff, LockBand, UnlockBand,
            Config5GDeployment, GetParamMAC, GetParamIMSI, GetPDUInfo, ExportMessageDetail,
            ExportLogfile, ConfigureAPN, SetupPDU, ReleasePDU, Config5GNRmeasurementAndEvent,
            SendAT, SetupS_NSSAI, GetAttachStatus, StartStatistics, StopStatistics, GetStatisticsResult,
            GetParamStatisticsResult, StartMOS, StopMOS, StartFTPDL, StartFTPUL, StartPing, StartHTTPPage,
            StopTest, StartCall, StartTraffic, StartCompositeTestPlan, GetParamSummaryStatisticsResult,
            PhysicalPowerOn, PhysicalPowerOff, Startup, Shutdown, PhysicalPowerOn, GetParamIMEI, GetCAParamMAC,
            GetParamValue, GetModuleStatus, GetPortStatus, ExportLogfileData, Reboot, GetAutoConnectInfo,
            GetDeviceInfo, StartPDUConn, SetAutoConnect, GetParamIP, Query5GNRmeasurementAndEvent,
            ExportLayer2Msg,  ExportLayer1Msg, GetModuleSlotInfo
        ]

        self._host = host
        self._port = port or 30999

        timeout = timeout or 60
        self._executor = TCPExecutor(self._host, self._port, default_retry_timeout=timeout)
        self._commands = []
        self._initialize_commands()

    @property
    def commands(self):
        return self._commands

    @property
    def host(self):
        return self._host

    @property
    def port(self):
        return self._port

    def _setup(self):
        self._executor.connect()

    def _teardown(self):
        self._executor.disconnect()

    def _initialize_commands(self):
        for command_cls in self._supported_commands:
            command = command_cls(self._executor)
            setattr(self, command_cls.__name__, command)
            self._commands.append(command)
